-- SANDBOX delta for CostPlus, generated by diffing the production (ALPERP) and SANDBOX inventories
-- taken on 2026-10-22. Schema only; no data is copied. For review before it is applied to SANDBOX.
-- Idempotent. Refuses to run anywhere except SANDBOX. ONE batch (no GO) so the guard stops everything.
--
-- Scope: objects the app references in CostPlus (FreightRequests, FreightProviderAbbreviations).
--   FreightProviderAbbreviations: identical on both sides.
--   FreightRequests: one column missing on SANDBOX (production column 122).
-- The ~100 other differences in CostPlus are unrelated tables and procedures the app never touches,
-- and are deliberately not migrated.

IF @@SERVERNAME <> 'SANDBOX' THROW 50020, 'Refusing to run: not connected to SANDBOX.', 1;

IF DB_NAME() <> 'CostPlus' THROW 50021, 'Refusing to run: connect to the CostPlus database.', 1;

IF COL_LENGTH('dbo.FreightRequests', 'Split') IS NULL
    ALTER TABLE dbo.FreightRequests ADD [Split] tinyint NULL;
